<template>
  <section class="external-api-shell">
    <header class="api-hero">
      <div><span class="eyebrow">CONNECTION LAB</span><h2>外接服务中心</h2><p>密钥、地址和超时配置统一保存在数据库中。保存后密钥不会再回显；启用后可直接进行安全测试。</p></div>
      <div class="hero-status"><span class="status-dot" />{{ configuredCount }} / {{ services.length }} 已配置</div>
    </header>

    <div class="service-groups">
      <section v-for="group in serviceGroups" :key="group.key" class="service-group"><header><span>{{ group.label }}</span><small>{{ group.note }}</small></header><div class="service-rail" role="tablist" :aria-label="group.label">
        <button v-for="service in group.services" :key="service.code" :class="{ active: selectedCode === service.code, ready: isReady(service) }" @click="selectService(service.code)">
          <strong>{{ service.mark }}</strong><span>{{ service.name }}</span><small>{{ isReady(service) ? '可测试' : service.requiresApiKey ? '待配置' : '已启用' }}</small>
        </button>
      </div></section>
    </div>

    <div class="external-api-grid">
      <section class="card config-card">
        <div class="section-title"><div class="service-mark">{{ selected.mark }}</div><div><span>{{ selected.kind === 'mt' ? '私有图库连接器' : '第三方服务连接器' }}</span><h3>{{ selected.name }}</h3></div></div>
        <p class="service-description">{{ selected.description }}</p>
        <el-form label-position="top" class="api-form" @submit.prevent>
          <el-form-item label="服务地址"><el-input v-model="form.baseUrl" :placeholder="selected.endpointHint" /></el-form-item>
          <el-form-item v-if="selected.requiresApiKey" :label="selected.keyLabel"><el-input v-model="form.apiKey" type="password" show-password :placeholder="keyPlaceholder" autocomplete="new-password" @focus="prepareApiKey" @input="apiKeyEdited=true" /></el-form-item>
          <div v-else class="no-key-hint">该连接器无需单独保存 API Key。</div>
          <div class="form-row"><el-form-item label="鉴权方式"><el-select v-model="form.authType"><el-option label="API Key" value="API_KEY" /><el-option label="无需鉴权" value="NONE" /></el-select></el-form-item><el-form-item label="超时"><el-input-number v-model="form.timeoutMs" :min="1000" :max="120000" :step="1000" /><span class="unit">ms</span></el-form-item></div>
          <el-form-item label="扩展配置 JSON"><el-input v-model="form.configJson" type="textarea" :rows="3" :placeholder="selected.configHint" /></el-form-item>
          <div class="toggle-line"><div><strong>启用此服务</strong><span>{{ selected.requiresApiKey ? '未启用或未保存密钥的服务不会参与业务查询。' : '关闭后该站内搜图服务不会参与封面候选。' }}</span></div><el-switch v-model="form.enabled" /></div>
          <div class="save-row"><span class="key-hint">{{ selected.requiresApiKey ? (form.apiKeyConfigured ? '密钥已在输入框中以星号掩码显示。' : '尚未保存密钥') : '无需保存密钥' }}</span><PrimaryButton label="保存配置" :loading="saving" @click="save" /></div>
        </el-form>
      </section>

      <section class="card test-card">
        <div class="test-heading"><div><span>LIVE TEST</span><h3>{{ selected.testTitle }}</h3></div><span class="endpoint">{{ selected.endpoint }}</span></div>
        <template v-if="selected.kind === 'mt'"><div class="mode-row"><button :class="{active: mode==='KEYWORD'}" @click="mode='KEYWORD'">关键词</button><button :class="{active: mode==='CLIP'}" @click="mode='CLIP'">CLIP 语义</button></div><div class="query-row"><el-input v-model="query" placeholder="例如：相机、户外、猫" @keyup.enter="runTest" /><PrimaryButton label="测试搜索" :loading="testing" @click="runTest" /></div><p class="test-note">{{ mode === 'CLIP' ? 'CLIP 需要 MT Photos 已完成智能识别与向量索引。' : '关键词搜索依赖图库已保存的文件名、元数据或文本信息。' }}</p></template>
        <template v-else-if="selected.kind === 'search'"><div class="query-row"><el-input v-model="query" placeholder="例如：索尼 A7C、机械键盘" @keyup.enter="runTest" /><PrimaryButton label="测试搜索" :loading="testing" @click="runTest" /></div><p class="test-note">请求会使用已保存的地址、密钥与扩展配置；返回结果仅用于验证连接。</p></template>
        <template v-else><p class="test-note check-note">remove.bg 没有无消耗健康检查接口。此操作只校验已保存的服务地址和 API Key；实际图片抠图才会消耗额度。</p><PrimaryButton label="校验配置" :loading="testing" @click="runTest" /></template>

        <div v-if="testError" class="test-error">{{ testError }}</div>
        <div v-else-if="mtResults" class="result-box"><div class="result-summary"><strong>{{ mtResults.totalCount }}</strong><span>条返回结果 · {{ mtResults.mode === 'CLIP' ? 'CLIP 语义' : '关键词' }}</span></div><div v-if="mtResults.items.length" class="result-grid"><article v-for="item in mtResults.items" :key="item.id" class="result-item" @click="preview({ url: item.thumbnailUrl, title: item.fileName || `图库文件 #${item.id}`, caption: detailsOf(item) })"><img :src="item.thumbnailUrl" :alt="item.fileName || `图库文件 ${item.id}`" /><div><strong>{{ item.fileName || `图库文件 #${item.id}` }}</strong><p>{{ detailsOf(item) }}</p></div></article></div><div v-else class="empty-result">搜索成功，但图库未返回匹配照片。</div><div v-if="mtResults.totalPages > 1" class="pagination-row"><button :disabled="mtResults.page===1 || testing" @click="loadMtPage(mtResults.page-1)">上一页</button><span>第 {{ mtResults.page }} / {{ mtResults.totalPages }} 页</span><button :disabled="mtResults.page===mtResults.totalPages || testing" @click="loadMtPage(mtResults.page+1)">下一页</button></div></div>
        <div v-else-if="genericResult" class="result-box"><div class="result-summary"><strong>{{ genericResult.resultCount }}</strong><span>{{ genericResult.message }}</span></div><div v-if="genericResult.items.length" class="result-grid"><article v-for="(item,index) in genericResult.items" :key="item.originalUrl || index" class="result-item" @click="item.originalUrl && preview({ url: item.originalUrl, title: item.title || `结果 #${index + 1}`, caption: item.sourceUrl || selected.name })"><img v-if="item.thumbnailUrl" :src="item.thumbnailUrl" :alt="item.title || '搜索结果'" /><div><strong>{{ item.title || `搜索结果 #${index + 1}` }}</strong><p>{{ item.sourceUrl || selected.name }}</p></div></article></div><div v-else class="empty-result">{{ genericResult.message }}</div></div>
        <div v-else class="test-empty"><span>⌁</span><p>{{ selected.kind === 'check' ? '保存后可校验凭据是否已就绪。' : '保存地址和密钥后，运行一次查询验证连接。' }}</p></div>
      </section>
    </div>
    <el-dialog v-model="previewVisible" width="min(900px, calc(100vw - 36px))" align-center destroy-on-close><template #header><div class="preview-title"><span>图片预览</span><strong>{{ previewItem?.title }}</strong></div></template><div v-if="previewItem" class="preview-stage"><img :src="previewItem.url" :alt="previewItem.title" /><p>{{ previewItem.caption }}</p></div></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import type { ExternalApiConfig, ExternalApiTestResponse, MtPhotosSearchItem, MtPhotosSearchResponse } from '@/types'
import { fetchExternalApiConfigs, saveExternalApiConfig, testExternalApiConfig, testMtPhotosSearch } from '@/api/settings'
import PrimaryButton from '@/components/PrimaryButton.vue'

type ServiceKind = 'mt' | 'search' | 'check'
type Service = { code: string; mark: string; name: string; description: string; endpoint: string; endpointHint: string; keyLabel: string; configHint: string; kind: ServiceKind; testTitle: string; group: 'network' | 'utility'; requiresApiKey: boolean }
const services: Service[] = [
  { code: 'JD_UNION_PRODUCT_SEARCH', mark: 'JD', name: '京东联盟商品搜索', description: '京东联盟正式商品接口，需要 AppKey、AppSecret 与联盟推广位。', endpoint: 'POST /JD_UNION_PRODUCT_SEARCH/test', endpointHint: 'https://api.jd.com/routerjson', keyLabel: '京东 AppSecret', configHint: '{"appKey":"","unionId":"","siteId":""}', kind: 'search', testTitle: '京东联盟测试', group: 'network', requiresApiKey: true },
  { code: 'TAOBAO_UNION_PRODUCT_SEARCH', mark: 'TB', name: '淘宝联盟商品搜索', description: '淘宝联盟正式物料搜索，可返回商品主图。', endpoint: 'POST /TAOBAO_UNION_PRODUCT_SEARCH/test', endpointHint: 'https://eco.taobao.com/router/rest', keyLabel: '淘宝 AppSecret', configHint: '{"appKey":"","adzoneId":""}', kind: 'search', testTitle: '淘宝联盟测试', group: 'network', requiresApiKey: true },
  { code: 'ICECAT_PRODUCT_CATALOG', mark: 'IC', name: 'Icecat 产品目录', description: '面向数码产品的官方规格和产品图目录，建议使用品牌 + 型号。', endpoint: 'POST /ICECAT_PRODUCT_CATALOG/test', endpointHint: 'https://live.icecat.biz/api', keyLabel: 'Icecat 凭据', configHint: '{"language":"zh"}', kind: 'search', testTitle: 'Icecat 目录测试', group: 'network', requiresApiKey: true },
  { code: 'BRAVE_IMAGE_SEARCH', mark: 'BR', name: 'Brave 图片搜索', description: '稳定的独立图片搜索 API，用作通用封面兜底。', endpoint: 'POST /BRAVE_IMAGE_SEARCH/test', endpointHint: 'https://api.search.brave.com/res/v1/images/search', keyLabel: 'Brave Subscription Token', configHint: '{"country":"CN","searchLang":"zh-hans","safeSearch":"strict"}', kind: 'search', testTitle: 'Brave 图片搜索测试', group: 'network', requiresApiKey: true },
  { code: 'SERPAPI_GOOGLE_IMAGES', mark: 'SG', name: 'SerpApi Google 商品图片', description: '可用 site: 参数限制来源域名，返回稳定的结构化缩略图。', endpoint: 'POST /SERPAPI_GOOGLE_IMAGES/test', endpointHint: 'https://serpapi.com/search.json', keyLabel: 'SerpApi API Key', configHint: '{"domains":["jd.com","taobao.com","tmall.com"],"gl":"cn","hl":"zh-CN"}', kind: 'search', testTitle: 'Google 商品图片测试', group: 'network', requiresApiKey: true },
  { code: 'MT_PHOTOS', mark: 'MT', name: 'MT Photos 图库', description: '按关键词或 CLIP 语义查询私有图库，并由后端代理缩略图。', endpoint: 'POST /gateway/search', endpointHint: 'https://photos.example.com', keyLabel: 'API Key', configHint: '可选，例如 {"galleryIds":[1,2]}', kind: 'mt', testTitle: '图库搜索测试', group: 'utility', requiresApiKey: true },
  { code: 'REMOVE_BG', mark: 'RB', name: 'remove.bg 智能抠图', description: '在保存封面时自动去除背景；测试不会发起图片处理，不消耗额度。', endpoint: 'POST /REMOVE_BG/test', endpointHint: 'https://api.remove.bg/v1.0/removebg', keyLabel: 'remove.bg API Key', configHint: '此服务不需要扩展配置', kind: 'check', testTitle: '配置校验', group: 'utility', requiresApiKey: true }
]
const selectedCode = ref(services[0].code), configs = ref<ExternalApiConfig[]>([]), saving = ref(false), testing = ref(false), query = ref(''), mode = ref<'KEYWORD' | 'CLIP'>('CLIP'), apiKeyEdited = ref(false)
const mtResults = ref<MtPhotosSearchResponse | null>(null), genericResult = ref<ExternalApiTestResponse | null>(null), testError = ref('')
const previewVisible = ref(false), previewItem = ref<{ url: string; title: string; caption: string } | null>(null)
const form = reactive<ExternalApiConfig & { apiKey: string; cseId: string }>({ apiCode: 'MT_PHOTOS', displayName: 'MT Photos 图库', baseUrl: '', authType: 'API_KEY', apiKey: '', cseId: '', apiKeyConfigured: false, maskedApiKey: null, configJson: '', timeoutMs: 15000, enabled: false })
const selected = computed(() => services.find(item => item.code === selectedCode.value) || services[0])
const serviceGroups = computed(() => [{ key: 'network', label: '网络图片搜索', note: '京东联盟 / 淘宝联盟 / Icecat / Brave', services: services.filter(item => item.group === 'network') }, { key: 'utility', label: '图库与图像处理', note: '私有图库 / 去背景', services: services.filter(item => item.group === 'utility') }])
const configuredCount = computed(() => services.filter(isReady).length)
const keyPlaceholder = computed(() => form.apiKeyConfigured ? '留空则保留当前密钥' : `粘贴 ${selected.value.name} 的 API Key`)
function configOf(code: string) { return configs.value.find(item => item.apiCode === code) }
function isReady(service: Service) { const config = configOf(service.code); return Boolean(config?.enabled && (!service.requiresApiKey || config.apiKeyConfigured)) }
function parseConfig(raw?: string | null) { try { return raw ? JSON.parse(raw) as Record<string, unknown> : {} } catch { return {} } }
function loadConfig(config?: ExternalApiConfig) { const defaults = selected.value; const extra = parseConfig(config?.configJson); apiKeyEdited.value=false; Object.assign(form, { apiCode: defaults.code, displayName: config?.displayName || defaults.name, baseUrl: config?.baseUrl || defaults.endpointHint, authType: config?.authType || 'API_KEY', apiKey: config?.apiKeyConfigured ? (config.maskedApiKey || '********') : '', cseId: typeof extra.cseId === 'string' ? extra.cseId : '', apiKeyConfigured: config?.apiKeyConfigured || false, maskedApiKey: config?.maskedApiKey || null, configJson: config?.configJson || '', timeoutMs: config?.timeoutMs || (defaults.code === 'REMOVE_BG' ? 120000 : 15000), enabled: config?.enabled || false }) }
function prepareApiKey(){if(!apiKeyEdited.value&&form.apiKeyConfigured)form.apiKey=''}
function selectService(code: string) { selectedCode.value = code; mtResults.value = null; genericResult.value = null; testError.value = ''; loadConfig(configOf(code)) }
async function load() { try { configs.value = await fetchExternalApiConfigs(); loadConfig(configOf(selectedCode.value)) } catch (error) { ElMessage.error((error as Error).message) } }
async function save() { if (!form.baseUrl.trim()) { ElMessage.warning('请填写服务地址'); return } saving.value = true; try { const saved = await saveExternalApiConfig(selected.value.code, { displayName: form.displayName, baseUrl: form.baseUrl, authType: form.authType, apiKey: apiKeyEdited.value && form.apiKey ? form.apiKey : undefined, configJson: form.configJson || undefined, timeoutMs: form.timeoutMs, enabled: form.enabled }); const index = configs.value.findIndex(item => item.apiCode === saved.apiCode); if (index >= 0) configs.value[index] = saved; else configs.value.push(saved); loadConfig(saved); ElMessage.success(`${selected.value.name} 配置已保存`) } catch (error) { ElMessage.error((error as Error).message) } finally { saving.value = false } }
async function runTest(page = 1) { if (selected.value.kind !== 'check' && !query.value.trim()) { ElMessage.warning('请输入搜索词'); return } testing.value = true; testError.value = ''; mtResults.value = null; genericResult.value = null; try { if (selected.value.kind === 'mt') mtResults.value = await testMtPhotosSearch({ query: query.value.trim(), mode: mode.value, page }); else genericResult.value = await testExternalApiConfig(selected.value.code, { query: query.value.trim() || undefined }) } catch (error) { testError.value = (error as Error).message } finally { testing.value = false } }
function loadMtPage(page: number) { runTest(page) }
function detailsOf(item: MtPhotosSearchItem) { return [item.id && `ID ${item.id}`, item.fileType, item.capturedAt].filter(Boolean).join(' · ') || 'MT Photos 返回的文件记录' }
function preview(item: { url: string; title: string; caption: string }) { previewItem.value = item; previewVisible.value = true }
onMounted(load)
</script>

<style scoped>
